// Live values — the two label controls are absent: labels bind nothing.
const val = (k) => ({ value: nb.get(k), type: typeof nb.get(k) });
return {
  size:   val('size'),
  colour: val('colour'),
  easing: val('easing'),
  loop:   val('loop'),
  // note: no 'Appearance' / 'Behaviour' here — label controls don't write to nb
};
